/** The Binder: a landscape picture book with a painted cover, read-aloud-sized type and an honest colophon.
 *  Daybreak storybook: cream paper, paper-cut edges, a sun-and-book mark, Fredoka display type, Literata story text. */
import PDFDocument from "pdfkit";
import { FONTS } from "./prompts.generated.js";
const INK = "#22223B", INK2 = "#3A3A5C", MUTED = "#6B6A80", PAPER = "#FFF8EC", PAPER2 = "#FFF1DA", TOMATO = "#FF6B4A", TOMATO_D = "#E04E2E", SUN = "#FFC233";
const SKY = "#4DA8DA", SKY_L = "#DCEFFA", LEAF = "#3BB273", LEAF_L = "#DDF3E6";
export function renderBook(b, pages, coverBytes, { forName, robot = false, teller = null } = {}) {
  return new Promise((resolve, reject) => {
    const W = 792, H = 612;
    const doc = new PDFDocument({ size: [W, H], margin: 0, autoFirstPage: true, info: { Title: b.title || "A Nightlight book", Author: "Nightlight Press", Creator: "Nightlight Press" } });
    // Fonts: FONTS (app/fonts, generated) first, then the Daybreak fonts embedded below, then EB Garamond, then PDF built-ins.
    const f = (...keys) => { for (const k of keys) { const s = FONTS[k] || EMBEDDED_FONTS[k]; if (s) return Buffer.from(s, "base64"); } return null; };
    doc.registerFont("Body", f("literata-400-normal", "ebg-400-normal") || "Times-Roman");
    doc.registerFont("Italic", f("literata-400-italic", "ebg-400-italic") || "Times-Italic");
    doc.registerFont("Display", f("fredoka-600-normal", "ebg-600-normal") || "Helvetica-Bold");
    const chunks = []; doc.on("data", (c) => chunks.push(c)); doc.on("end", () => resolve(Buffer.concat(chunks))); doc.on("error", reject);
    const bg = (c) => { doc.save(); doc.rect(0, 0, W, H).fill(c); doc.restore(); };
    const noBreak = (fn) => { const m = doc.page.margins.bottom; doc.page.margins.bottom = 0; fn(); doc.page.margins.bottom = m; };
    const title = b.title || "";
    /** Largest size in [min, max] at which `text` fits on one line of `width` (a two-line wrap still happens below min). */
    const fitWidth = (font, text, max, min, width) => { doc.font(font); let s = max; for (; s > min; s -= 1) { doc.fontSize(s); if (doc.widthOfString(text) <= width) break; } doc.fontSize(s); return s; };
    /** The site's sun-and-book mark (LOGO in views/layout.js), drawn at `size` points with its top-left at x, y. */
    const mark = (x, y, size) => {
      doc.save(); doc.translate(x, y).scale(size / 32);
      doc.circle(16, 16, 15).fill(TOMATO);
      doc.path("M16 6.2v1.6M10.9 8.4l1.1 1.1M21.1 8.4l-1.1 1.1M8.6 12.2l1.5.4M23.4 12.2l-1.5.4").lineWidth(1.6).lineCap("round").stroke(SUN);
      doc.circle(16, 14, 3.9).fill(SUN);
      doc.path("M5.8 17.6c3.4-1.7 7-1.6 10.2.5v7.6c-3.2-2-6.8-2.1-10.2-.5z").fill(PAPER);
      doc.path("M26.2 17.6c-3.4-1.7-7-1.6-10.2.5v7.6c3.2-2 6.8-2.1 10.2-.5z").fill(PAPER2);
      doc.path("M16 18.1v7.6").lineWidth(1).lineCap("round").stroke(TOMATO_D);
      doc.restore();
    };
    /** "Nightlight Press" imprint: the mark plus the name, centred on cy. */
    const imprint = (cy, color = MUTED) => {
      doc.font("Display").fontSize(11); const tw = doc.widthOfString("Nightlight Press"), total = 22 + 8 + tw, x = (W - total) / 2;
      mark(x, cy - 11, 22);
      doc.fillColor(color).text("Nightlight Press", x + 30, cy - doc.currentLineHeight() / 2 + 0.5, { lineBreak: false });
    };
    /** The book's ornament: a little sun-yellow sun between two soft tomato hairlines. */
    const ornament = (cx, cy, r = 9) => {
      doc.save();
      doc.lineWidth(0.75).strokeOpacity(0.4).strokeColor(TOMATO);
      doc.moveTo(cx - r * 2.6 - 96, cy).lineTo(cx - r * 2.6 - 6, cy).stroke().moveTo(cx + r * 2.6 + 6, cy).lineTo(cx + r * 2.6 + 96, cy).stroke();
      doc.strokeOpacity(1).lineWidth(Math.max(2, r * 0.26)).lineCap("round").strokeColor(SUN);
      for (let i = 0; i < 8; i++) { const a = (i * Math.PI) / 4 + Math.PI / 8; doc.moveTo(cx + Math.cos(a) * r * 1.5, cy + Math.sin(a) * r * 1.5).lineTo(cx + Math.cos(a) * r * 2.1, cy + Math.sin(a) * r * 2.1).stroke(); }
      doc.lineWidth(1.2).circle(cx, cy, r).fillAndStroke(SUN, TOMATO_D);
      doc.restore();
    };
    /** A gently wavy line across the page at y; `wave` closes it down to `bottom` (paper-cut hills, torn-paper bands). */
    const waveY = (x, y, amp, len, phase) => y + amp * Math.sin((x / len) * 2 * Math.PI + phase) + amp * 0.35 * Math.sin((x / len) * 4.6 * Math.PI + phase * 1.7);
    const edge = (y, amp, len, phase) => { doc.moveTo(0, waveY(0, y, amp, len, phase)); for (let x = 6; x < W + 6; x += 6) doc.lineTo(Math.min(x, W), waveY(Math.min(x, W), y, amp, len, phase)); };
    const wave = (y, amp, len, phase, bottom = H) => { edge(y, amp, len, phase); doc.lineTo(W, bottom).lineTo(0, bottom).closePath(); };
    /** One cut-paper layer: the layer itself, then a darker lip along its top edge. */
    const paperLayer = (y, amp, len, phase, fill, opacity, lip, lipOpacity) => {
      doc.save(); wave(y, amp, len, phase); doc.fillOpacity(opacity).fill(fill); doc.restore();
      doc.save(); edge(y + 1, amp, len, phase); doc.lineWidth(3).lineJoin("round").strokeOpacity(lipOpacity).stroke(lip); doc.restore();
    };

    // ---- Cover: the painted art under a cream paper-cut title plaque with a pressed tomato edge ----
    bg(PAPER2);
    if (coverBytes) { try { doc.image(coverBytes, 0, 0, { cover: [W, H], align: "center", valign: "center" }); } catch { /* typographic cover */ } }
    {
      const sub = teller ? `From a story told by ${teller}` : forName ? `A Nightlight book starring ${forName}` : "A Nightlight book";
      const maxTW = W - 80 - 72;
      fitWidth("Display", title, 38, 28, maxTW);
      const tw = Math.min(maxTW, doc.widthOfString(title)), th = doc.heightOfString(title, { width: maxTW, align: "center" });
      doc.font("Italic").fontSize(15); const sw = doc.widthOfString(sub), sh = doc.currentLineHeight();
      const pw = Math.min(W - 80, Math.max(440, tw + 80, sw + 80)), ph = 22 + th + 4 + sh + 20, px = (W - pw) / 2, py = 24;
      doc.save();
      for (const [dy, o] of [[12, 0.05], [8, 0.07], [5, 0.08]]) doc.roundedRect(px - 3, py + dy, pw + 6, ph, 27).fillOpacity(o).fill(INK);
      doc.roundedRect(px, py + 5, pw, ph, 24).fillOpacity(1).fill(TOMATO_D);
      doc.roundedRect(px, py, pw, ph, 24).fillOpacity(0.96).fill(PAPER);
      doc.restore();
      noBreak(() => {
        fitWidth("Display", title, 38, 28, maxTW);
        doc.fillColor(INK).text(title, px + 36, py + 20, { width: pw - 72, align: "center" });
        doc.font("Italic").fontSize(15).fillColor(INK2).text(sub, px + 24, doc.y + 4, { width: pw - 48, align: "center", lineBreak: false });
      });
      // Publisher's seal, bottom right, like a real picture-book cover.
      doc.save(); doc.circle(W - 46, H - 46, 24).fillOpacity(0.95).fill(PAPER); doc.restore();
      mark(W - 46 - 19, H - 46 - 19, 38);
    }

    // ---- Half-title + dedication, with the imprint at the foot ----
    doc.addPage(); bg(PAPER);
    noBreak(() => {
      const tW = W - 200, dW = W - 240;
      fitWidth("Display", title, 34, 26, tW); const tH = doc.heightOfString(title, { width: tW, align: "center" }), tS = doc._fontSize;
      doc.font("Italic").fontSize(17); const dH = b.dedication ? doc.heightOfString(b.dedication, { width: dW, align: "center", lineGap: 2 }) : 0;
      const block = 40 + 30 + tH + (dH ? 36 + dH : 0), y0 = Math.max(70, (H - 100 - block) / 2 + 24);
      ornament(W / 2, y0 + 20);
      doc.fillColor(INK).font("Display").fontSize(tS).text(title, (W - tW) / 2, y0 + 70, { width: tW, align: "center" });
      if (dH) doc.font("Italic").fontSize(17).fillColor(MUTED).text(b.dedication, (W - dW) / 2, doc.y + 36, { width: dW, align: "center", lineGap: 2 });
      imprint(H - 72);
    });

    // ---- Story pages: full-bleed art with a torn-paper edge, read-aloud text centred in the band below ----
    for (const pg of pages) {
      doc.addPage(); bg(PAPER);
      const imgH = 452;
      if (pg.bytes) {
        try { doc.save(); doc.rect(0, 0, W, imgH).clip(); doc.image(pg.bytes, 0, 0, { cover: [W, imgH], align: "center", valign: "center" }); doc.restore(); } catch { /* skip */ }
        const ph = (pg.idx || 0) * 1.3;
        for (const [dy, o] of [[4.5, 0.05], [3, 0.07], [1.5, 0.09]]) { doc.save(); wave(imgH - 8 - dy, 6, 264, ph); doc.fillOpacity(o).fill(INK); doc.restore(); }
        doc.save(); wave(imgH - 8, 6, 264, ph); doc.fill(PAPER); doc.restore();
      }
      const text = String(pg.text || ""), tW = W - 150, top = imgH + 8, bottom = H - 30, opts = { width: tW, align: "center", lineGap: 4 };
      doc.font("Body"); let fs = 20; for (; fs > 14; fs -= 1) { doc.fontSize(fs); if (doc.heightOfString(text, opts) <= bottom - top) break; }
      doc.fontSize(fs); const h = doc.heightOfString(text, opts);
      noBreak(() => {
        doc.fillColor(INK).text(text, (W - tW) / 2, top + Math.max(0, (bottom - top - h) / 2), { ...opts, height: H - top - 6 });
        const n = String(pg.idx ?? ""); doc.font("Display").fontSize(10.5); const nw = Math.max(24, doc.widthOfString(n) + 14), nx = W - 32 - nw, ny = H - 32 - 18;
        doc.roundedRect(nx, ny, nw, 18, 9).fill(PAPER2);
        doc.fillColor(MUTED).text(n, nx, ny + 9 - doc.currentLineHeight() / 2 + 0.5, { width: nw, align: "center", lineBreak: false });
      });
    }

    // ---- Learn about robots: three true facts the Author wrote for this reader ----
    const facts = (b.story && Array.isArray(b.story.robot_facts) ? b.story.robot_facts : []).slice(0, 3);
    if (facts.length) {
      doc.addPage(); bg(SKY_L);
      noBreak(() => {
        doc.fillColor(INK).font("Display").fontSize(34).text("Learn about robots", 60, 70, { width: W - 120, align: "center" });
        doc.font("Italic").fontSize(14).fillColor(INK2).text("Three true things to wonder about together", 60, 116, { width: W - 120, align: "center" });
        facts.forEach((f, i) => {
          const y = 175 + i * 128; const cx = 118;
          doc.save(); doc.circle(cx, y + 30, 30).fill([TOMATO, SUN, LEAF][i % 3]); doc.restore();
          // a tiny robot face in each badge
          doc.save(); doc.roundedRect(cx - 15, y + 17, 30, 24, 6).fill("#FFFFFF"); doc.circle(cx - 6, y + 29, 3.2).fill(INK); doc.circle(cx + 6, y + 29, 3.2).fill(INK); doc.moveTo(cx, y + 17).lineTo(cx, y + 9).lineWidth(2).stroke(INK); doc.circle(cx, y + 8, 3).fill(SUN); doc.restore();
          doc.fillColor(INK).font("Body").fontSize(21).text(String(f), 170, y + 8, { width: W - 250, lineGap: 3 });
        });
      });
    }

    // ---- The End, over paper-cut hills, with the colophon and the mark ----
    doc.addPage(); bg(PAPER2);
    paperLayer(548, 11, 560, 0.7, SKY_L, 1, SKY, 0.5);
    paperLayer(570, 9, 470, 2.3, LEAF_L, 1, LEAF, 0.45);
    paperLayer(592, 6, 380, 4.1, LEAF, 0.55, LEAF, 1);
    ornament(W / 2, 128);
    noBreak(() => {
      doc.font("Display").fontSize(46); const ew = doc.widthOfString("The End"), ey = 162, base = ey + (doc._font.ascender / 1000) * 46;
      doc.save(); doc.roundedRect((W - ew) / 2 - 6, base - 9, ew + 12, 12, 6).fillOpacity(0.9).fill(SUN); doc.restore();
      doc.fillColor(INK).text("The End", 40, ey, { width: W - 80, align: "center" });
      doc.font("Italic").fontSize(16).fillColor(INK2).text("Sweet dreams.", 40, doc.y + 6, { width: W - 80, align: "center" });
      if (b.blurb) doc.font("Body").fontSize(13).fillColor(INK).text(b.blurb, 140, doc.y + 30, { width: W - 280, align: "center", lineGap: 3, height: 110 });
      imprint(440, INK);
      const c = b.checks || {};
      doc.font("Body").fontSize(9.5).fillColor(MUTED).text(`Written by Nightlight’s Author, illustrated by its Illustrator, narrated by its Narrator and bound by its Binder: AI staff at a publisher with no employees. Checked by the Editor before a single picture was painted${c.reading_grade != null ? ` (reading grade ${c.reading_grade}, ${c.words} words)` : ""}.${teller ? ` Adapted from a story told aloud by ${teller}.` : ""}${robot ? " Featuring Pip, a PlayRobot character, included at the family's request." : ""}`, 100, 462, { width: W - 200, align: "center", lineGap: 1.5 });
    });
    doc.end();
  });
}

/* Daybreak book fonts (SIL Open Font License, Google Fonts), subset to Latin + Vietnamese, base64 TTF:
   Literata 400 / 400 italic for story text, Fredoka 600 for display. Moving these TTFs into app/fonts/ makes FONTS win and this block unnecessary. */
const EMBEDDED_FONTS = {"literata-400-normal":"","literata-400-italic":"","fredoka-600-normal":""};
